        while len(char_count) > len(set(char_count)):
            char = s[left]
            char_count[char] -= 1
            if char_count[char] == 0:
                del char_count[char]
            left += 1

        if right - left + 1 < min_length:
            min_length = right - left + 1
            result = s[left:right+1]

        right += 1

    return result

