        if char in freq_str1:
            freq_str1[char] += 1
        else:
            freq_str1[char] = 1

    # Count characters in str2
    for char in str2:
        if char in freq_str2:
            freq_str2[char] += 1
        else:
            freq_str2[char] = 1

    # Compare the frequency dictionaries
    return freq_str1 == freq_str2

