def countVowelStrings(n):
    dp = [[0] * 6 for _ in range(n + 1)]

    # Base case
    for j in range(6):
        dp[n][j] = 1

    # Fill the DP table
    for i in range(n - 1, -1, -1):
        for j in range(6):
            if j == 0:
                dp[i][j] = dp[i + 1][j]
            else:
                dp[i][j] = dp[i + 1][j] + dp[i][j - 1]

    return dp[0][5]

