def smallest_missing_positive(nums):
    n = len(nums)

    # Mark the presence of numbers using negative values
    for i in range(n):
        if abs(nums[i]) <= n and nums[abs(nums[i]) - 1] > 0:
            nums[abs(nums[i]) - 1] *= -1

    # Find the first positive number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If all numbers are present, return n + 1
