def minSessions(tasks, sessionTime):
    n = len(tasks)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            if tasks[j] <= sessionTime:
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]

