def encodeString(s: str) -> str:
    stack = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            count = int(s[i])
            j = i + 1
            while j < len(s) and s[j].isdigit():
                j += 1
            count *= int(s[i:j])
            i = j - 1
        elif s[i] == '[':
            stack.append(count)
            count = 0
        else:
            stack.append(s[i])
        i += 1
    return ''.join(stack)

