def find_kth_smallest(mat, k):
    def is_valid(x):
        i, j = len(mat) - 1, 0
        while i >= 0 and j < len(mat[0]):
            if mat[i][j] <= x:
                j += 1
            else:
                i -= 1
        return j

    left, right = mat[0][0], mat[-1][-1]
    while left < right:
        mid = (left + right) // 2
