def bit_xor(arr1, arr2):
    # Check if both arrays are of the same length
    if len(arr1) != len(arr2):
        # Find the minimum length of the two arrays
        min_len = min(len(arr1), len(arr2))
        # Perform XOR operation up to the minimum length
        return [arr1[i] ^ arr2[i] for i in range(min_len)]
    else:
        # Perform XOR operation on all elements
        return [arr1[i] ^ arr2[i] for i in range(len(arr1))]

